import{_ as e,o,c as i,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Planificación Académica: Algorítmica y Programación (Trayecto I)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Algoritmica_y_Programacion/Planificacion_Trimestre_I-I.md","filePath":"materias/Algoritmica_y_Programacion/Planificacion_Trimestre_I-I.md"}'),r={name:"materias/Algoritmica_y_Programacion/Planificacion_Trimestre_I-I.md"};function s(l,a,t,c,d,u){return o(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="planificacion-academica-algoritmica-y-programacion-trayecto-i" tabindex="-1">Planificación Académica: Algorítmica y Programación (Trayecto I) <a class="header-anchor" href="#planificacion-academica-algoritmica-y-programacion-trayecto-i" aria-label="Permalink to &quot;Planificación Académica: Algorítmica y Programación (Trayecto I)&quot;">​</a></h1><p>Este documento detalla la planificación del Trimestre 1, dividido en 4 evaluaciones principales.</p><hr><h2 id="📅-trimestre-1-fundamentos-y-logica-con-javascript" tabindex="-1">📅 Trimestre 1: Fundamentos y Lógica con JavaScript <a class="header-anchor" href="#📅-trimestre-1-fundamentos-y-logica-con-javascript" aria-label="Permalink to &quot;📅 Trimestre 1: Fundamentos y Lógica con JavaScript&quot;">​</a></h2><h3 id="📝-evaluacion-1-fundamentos-de-programacion-y-logica-basica" tabindex="-1">📝 Evaluación 1: Fundamentos de Programación y Lógica Básica <a class="header-anchor" href="#📝-evaluacion-1-fundamentos-de-programacion-y-logica-basica" aria-label="Permalink to &quot;📝 Evaluación 1: Fundamentos de Programación y Lógica Básica&quot;">​</a></h3><h2 id="examen-escrito" tabindex="-1">Examen escrito <a class="header-anchor" href="#examen-escrito" aria-label="Permalink to &quot;Examen escrito&quot;">​</a></h2><p><strong>Objetivo:</strong> Comprender qué es la programación, cómo se comunica el humano con la máquina y los componentes básicos de un algoritmo.</p><h4 id="_1-conceptos-teoricos" tabindex="-1">1. Conceptos Teóricos <a class="header-anchor" href="#_1-conceptos-teoricos" aria-label="Permalink to &quot;1. Conceptos Teóricos&quot;">​</a></h4><ul><li><strong>¿Qué es la programación?:</strong> El arte de dar instrucciones (receta de cocina).</li><li><strong>El Programa vs Hardware:</strong> Secuencia lógica (mente) vs parte física (cuerpo).</li><li><strong>Lenguajes de Programación:</strong><ul><li><strong>Nivel Bajo:</strong> Binario y Ensamblador (proximidad al hardware).</li><li><strong>Nivel Alto:</strong> JavaScript, Python, C++ (palabras similares al inglés).</li></ul></li><li><strong>Traducción del Código:</strong><ul><li><strong>Compiladores:</strong> Traducen todo el bloque antes de ejecutar.</li><li><strong>Intérpretes:</strong> Traducción línea por línea (Ej: JavaScript/Node.js).</li></ul></li></ul><h4 id="_2-logica-y-algoritmos" tabindex="-1">2. Lógica y Algoritmos <a class="header-anchor" href="#_2-logica-y-algoritmos" aria-label="Permalink to &quot;2. Lógica y Algoritmos&quot;">​</a></h4><ul><li><strong>Definición de Algoritmo:</strong> Conjunto finito, ordenado y preciso de pasos.</li><li><strong>Características:</strong> Preciso (orden), Definido (mismo resultado), Finito (tiene fin).</li><li><strong>Representación (Pseudocódigo):</strong> Uso de palabras clave para describir la lógica.</li><li><strong>Traza de un Algoritmo (Corrida en Frío):</strong> Verificación manual paso a paso mediante tablas de seguimiento de variables en memoria.</li></ul><h4 id="_3-metodologia-de-las-4-fases-estandar-del-profesor" tabindex="-1">3. Metodología de las 4 Fases (Estándar del Profesor) <a class="header-anchor" href="#_3-metodologia-de-las-4-fases-estandar-del-profesor" aria-label="Permalink to &quot;3. Metodología de las 4 Fases (Estándar del Profesor)&quot;">​</a></h4><p>Para todo ejercicio de lógica y código, se debe seguir estrictamente este orden:</p><ol><li><strong>Declaración:</strong> Identificar y crear las etiquetas/variables necesarias para guardar datos.</li><li><strong>Entrada:</strong> Solicitar y capturar los datos (instrucciones Leer / prompt).</li><li><strong>Cálculo:</strong> Realizar las operaciones matemáticas o lógicas.</li><li><strong>Salida:</strong> Mostrar los resultados obtenidos.</li></ol><p><strong>Ejemplo A: Saludo Personalizado</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Inicio</span></span>
<span class="line"><span>    // 1. Declaración</span></span>
<span class="line"><span>    nombre: Cadena</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 2. Entrada</span></span>
<span class="line"><span>    Escribir &quot;Por favor, ingresa tu nombre:&quot;</span></span>
<span class="line"><span>    Leer nombre</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 3. Cálculo (N/A en este ejemplo)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 4. Salida</span></span>
<span class="line"><span>    Escribir &quot;Hola, &quot; + nombre + &quot;. ¡Bienvenido a Algorítmica!&quot;</span></span>
<span class="line"><span>Fin</span></span></code></pre></div><p><strong>Ejemplo B: Suma de dos números</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Inicio</span></span>
<span class="line"><span>    // 1. Declaración</span></span>
<span class="line"><span>    num1, num2, resultado: Entero</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 2. Entrada</span></span>
<span class="line"><span>    Escribir &quot;Ingresa el primer número:&quot;</span></span>
<span class="line"><span>    Leer num1</span></span>
<span class="line"><span>    Escribir &quot;Ingresa el segundo número:&quot;</span></span>
<span class="line"><span>    Leer num2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 3. Cálculo</span></span>
<span class="line"><span>    resultado = num1 + num2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 4. Salida</span></span>
<span class="line"><span>    Escribir &quot;La suma total es: &quot; + resultado</span></span>
<span class="line"><span>Fin</span></span></code></pre></div><h4 id="_4-entidades-primitivas-y-datos" tabindex="-1">4. Entidades Primitivas y Datos <a class="header-anchor" href="#_4-entidades-primitivas-y-datos" aria-label="Permalink to &quot;4. Entidades Primitivas y Datos&quot;">​</a></h4><ul><li><strong>Dato vs. Información:</strong> Unidad mínima aislada frente a datos procesados con contexto.</li><li><strong>Tipos de Datos Primitivos:</strong><ul><li>Enteros (Integer) y Reales (Float/Double).</li><li>Caracteres (Char/String) y Booleanos (True/False).</li></ul></li><li><strong>Contenedores de Memoria e Identificadores:</strong><ul><li><strong>Reglas de Identificadores:</strong> Claridad semántica y convención <code>camelCase</code> / <code>UPPER_SNAKE_CASE</code>.</li><li><strong>Variables:</strong> Valores que cambian (clasificadas por su uso en: <strong>De trabajo</strong>, <strong>Contadores</strong> y <strong>Acumuladores</strong>).</li><li><strong>Constantes:</strong> Valores fijos e inmutables (Ej: <code>PI</code>, <code>IVA</code>).</li></ul></li><li><strong>Operadores Aritméticos y Expresiones:</strong> <code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>%</code> (Módulo) y jerarquía de evaluación.</li></ul><hr><h3 id="📝-evaluacion-2-el-entorno-de-desarrollo-y-la-transicion-al-codigo" tabindex="-1">📝 Evaluación 2: El Entorno de Desarrollo y la Transición al Código <a class="header-anchor" href="#📝-evaluacion-2-el-entorno-de-desarrollo-y-la-transicion-al-codigo" aria-label="Permalink to &quot;📝 Evaluación 2: El Entorno de Desarrollo y la Transición al Código&quot;">​</a></h3><h2 id="examen-escrito-1" tabindex="-1">Examen escrito <a class="header-anchor" href="#examen-escrito-1" aria-label="Permalink to &quot;Examen escrito&quot;">​</a></h2><p><strong>Objetivo:</strong> Comprender el ecosistema de desarrollo moderno, dominar la terminal, aplicar estándares de calidad/diagramación bajo norma ISO 5807 e instalar las herramientas necesarias para traducir lógica a código real.</p><h4 id="_1-scripts-y-ejecucion" tabindex="-1">1. Scripts y Ejecución <a class="header-anchor" href="#_1-scripts-y-ejecucion" aria-label="Permalink to &quot;1. Scripts y Ejecución&quot;">​</a></h4><ul><li><strong>¿Qué es un Script?:</strong> Archivo de texto con comandos ejecutados por un intérprete (la &quot;receta&quot; en tiempo real).</li><li><strong>Análisis Comparativo:</strong><ul><li><strong>Compilación (C++, Rust):</strong> Traducción previa integral (como traducir un libro entero).</li><li><strong>Interpretación (JS, Python):</strong> Traducción línea por línea en tiempo real (como un intérprete en vivo).</li></ul></li><li><strong>Rendimiento y Flexibilidad:</strong> Evolución con JIT (Just-In-Time).</li></ul><h4 id="_2-herramientas-del-programador-y-estandares-de-calidad-unidad-2" tabindex="-1">2. Herramientas del Programador y Estándares de Calidad (Unidad 2) <a class="header-anchor" href="#_2-herramientas-del-programador-y-estandares-de-calidad-unidad-2" aria-label="Permalink to &quot;2. Herramientas del Programador y Estándares de Calidad (Unidad 2)&quot;">​</a></h4><ul><li><strong>Editor de Código vs IDE:</strong> VS Code/Sublime (Ligeros) vs IntelliJ/Eclipse (Pesados) vs IDE Agéntico.</li><li><strong>Funcionalidades Críticas:</strong> Resaltado de sintaxis, IntelliSense, Emparejamiento de delimitadores, Autoindentación e integración con Git.</li><li><strong>Estándares de Calidad y Documentación:</strong> Código autodocumentado, comentarios explicativos (<code>//</code>, <code>/* */</code>), nomenclatura estándar y formateo consistente.</li></ul><h4 id="_3-interfaz-de-linea-de-comandos-cli" tabindex="-1">3. Interfaz de Línea de Comandos (CLI) <a class="header-anchor" href="#_3-interfaz-de-linea-de-comandos-cli" aria-label="Permalink to &quot;3. Interfaz de Línea de Comandos (CLI)&quot;">​</a></h4><ul><li><strong>Navegación Básica:</strong><ul><li><code>pwd</code>: Ruta actual.</li><li><code>ls</code> / <code>dir</code>: Listar archivos.</li><li><code>cd</code>: Cambiar de directorio.</li><li><code>mkdir</code> / <code>touch</code>: Crear carpetas y archivos.</li><li><code>rm</code> / <code>del</code>: Eliminar elementos.</li></ul></li></ul><h4 id="_4-el-ecosistema-javascript-y-node-js" tabindex="-1">4. El Ecosistema JavaScript y Node.js <a class="header-anchor" href="#_4-el-ecosistema-javascript-y-node-js" aria-label="Permalink to &quot;4. El Ecosistema JavaScript y Node.js&quot;">​</a></h4><ul><li><strong>JavaScript:</strong> El lenguaje universal (Frontend y Backend).</li><li><strong>Motor V8:</strong> El motor de Chrome que da velocidad a JS.</li><li><strong>Node.js:</strong> Entorno de ejecución fuera del navegador. <ul><li>Arquitectura asíncrona y Event Loop (No bloqueante).</li></ul></li><li><strong>npm:</strong> El gestor de paquetes más grande del mundo (Gestión de dependencias y <code>package.json</code>).</li></ul><h4 id="_5-representacion-grafica-ingenieria-de-diagramas-de-flujo-norma-iso-5807-ansi" tabindex="-1">5. Representación Gráfica: Ingeniería de Diagramas de Flujo (Norma ISO 5807 / ANSI) <a class="header-anchor" href="#_5-representacion-grafica-ingenieria-de-diagramas-de-flujo-norma-iso-5807-ansi" aria-label="Permalink to &quot;5. Representación Gráfica: Ingeniería de Diagramas de Flujo (Norma ISO 5807 / ANSI)&quot;">​</a></h4><ul><li><strong>Simbología Estándar Normalizada:</strong><ul><li><strong>Terminal (Óvalo):</strong> Inicio y Final del algoritmo.</li><li><strong>Proceso (Rectángulo):</strong> Operaciones aritméticas y asignaciones en memoria.</li><li><strong>Entrada / Salida General (Paralelogramo):</strong> Captura e impresión de datos (<code>Leer</code> / <code>Escribir</code>).</li><li><strong>Decisión (Rombo):</strong> Evaluación condicional booleana con bifurcación etiquetada (<em>Sí/No</em>).</li><li><strong>Conectores (Círculo / Pentágono) y Subprocesos:</strong> Enlace dentro de la misma página, fuera de página y llamadas a módulos.</li></ul></li><li><strong>Reglas de Diseño Estructural:</strong> Direccionalidad <em>top-down</em>, ortogonalidad de líneas de flujo, unicidad de entrada/salida y representación de los tres patrones del Teorema de Böhm-Jacopini (secuencia, selección e iteración).</li></ul><h4 id="💻-practica-de-transicion" tabindex="-1">💻 Práctica de Transición <a class="header-anchor" href="#💻-practica-de-transicion" aria-label="Permalink to &quot;💻 Práctica de Transición&quot;">​</a></h4><ul><li>Instalación de Node.js (LTS) y VS Code (o entorno móvil Termux).</li><li><strong>De la lógica al código:</strong> Refuerzo de las 4 Fases en Pseudocódigo y su primera traducción a JavaScript real usando <code>console.log()</code> y <code>prompt-sync</code>.</li></ul><hr><h3 id="📝-evaluacion-3-arquitectura-de-la-logica-de-control" tabindex="-1">📝 Evaluación 3: Arquitectura de la Lógica de Control <a class="header-anchor" href="#📝-evaluacion-3-arquitectura-de-la-logica-de-control" aria-label="Permalink to &quot;📝 Evaluación 3: Arquitectura de la Lógica de Control&quot;">​</a></h3><h2 id="examen-escrito-2" tabindex="-1">Examen escrito <a class="header-anchor" href="#examen-escrito-2" aria-label="Permalink to &quot;Examen escrito&quot;">​</a></h2><p><strong>Objetivo:</strong> Dominar la toma de decisiones en el código mediante estructuras condicionales, álgebra de Boole y patrones de refactorización profesional en JavaScript.</p><h4 id="_1-epistemologia-y-fundamentos" tabindex="-1">1. Epistemología y Fundamentos <a class="header-anchor" href="#_1-epistemologia-y-fundamentos" aria-label="Permalink to &quot;1. Epistemología y Fundamentos&quot;">​</a></h4><ul><li><strong>Evolución de la Lógica:</strong> De los saltos incondicionales (GOTO) a la Programación Estructurada.</li><li><strong>Definición de Estructuras de Decisión:</strong> Instrucciones que rompen la linealidad del código basándose en expresiones booleanas.</li></ul><h4 id="_2-operadores-y-algebra-de-boole" tabindex="-1">2. Operadores y Álgebra de Boole <a class="header-anchor" href="#_2-operadores-y-algebra-de-boole" aria-label="Permalink to &quot;2. Operadores y Álgebra de Boole&quot;">​</a></h4><ul><li><strong>Operadores Relacionales:</strong><ul><li>Diferencia crítica: Igualdad abstracta (<code>==</code>) vs. <strong>Igualdad estricta (<code>===</code>)</strong>.</li><li>Desigualdad, Mayor, Menor, Mayor/Menor o igual.</li></ul></li><li><strong>Conectores Lógicos (Tablas de Verdad):</strong><ul><li><strong>AND (<code>&amp;&amp;</code>):</strong> Restricción (todas deben cumplirse).</li><li><strong>OR (<code>||</code>):</strong> Flexibilidad (al menos una debe cumplirse).</li><li><strong>NOT (<code>!</code>):</strong> Inversión de polaridad lógica.</li></ul></li></ul><h4 id="_3-implementacion-de-condicionales-en-js" tabindex="-1">3. Implementación de Condicionales en JS <a class="header-anchor" href="#_3-implementacion-de-condicionales-en-js" aria-label="Permalink to &quot;3. Implementación de Condicionales en JS&quot;">​</a></h4><ul><li><strong>Estructura If / Else / Else If:</strong> Gestión de bloques con llaves <code>{}</code> y prevención de errores estructurales.</li><li><strong>Estructura Switch:</strong> Optimización de múltiples casos, el concepto de <em>fall-through</em> y el uso obligatorio de <code>break</code>.</li><li><strong>Operador Ternario:</strong> Sintaxis <code>? :</code> para asignaciones directas y fomento de la inmutabilidad (<code>const</code>).</li></ul><h4 id="_4-semantica-de-datos-truthy-y-falsy" tabindex="-1">4. Semántica de Datos: Truthy y Falsy <a class="header-anchor" href="#_4-semantica-de-datos-truthy-y-falsy" aria-label="Permalink to &quot;4. Semántica de Datos: Truthy y Falsy&quot;">​</a></h4><ul><li><strong>Coerción de tipos:</strong> Cómo JavaScript evalúa valores no booleanos en contextos lógicos.</li><li><strong>Los 8 Valores Falsy:</strong> <code>false</code>, <code>0</code>, <code>-0</code>, <code>0n</code>, <code>&quot;&quot;</code>, <code>null</code>, <code>undefined</code>, <code>NaN</code>.</li><li><strong>Valores Truthy:</strong> Todo lo que no es falsy (incluyendo <code>[]</code> y <code>{}</code>).</li></ul><h4 id="_5-logica-avanzada-y-refactorizacion" tabindex="-1">5. Lógica Avanzada y Refactorización <a class="header-anchor" href="#_5-logica-avanzada-y-refactorizacion" aria-label="Permalink to &quot;5. Lógica Avanzada y Refactorización&quot;">​</a></h4><ul><li><strong>Evaluación de Cortocircuito:</strong> Uso de <code>&amp;&amp;</code> para lógica defensiva y <code>||</code> para valores de respaldo (<em>fallbacks</em>).</li><li><strong>Operador de Coalescencia Nula (<code>??</code>):</strong> Manejo preciso de <code>null</code> y <code>undefined</code>.</li><li><strong>Patrones Profesionales:</strong><ul><li><strong>Cláusulas de Guarda (Guard Clauses):</strong> Retornos tempranos para eliminar el anidamiento excesivo.</li><li><strong>Mapeo de Objetos:</strong> Sustitución de <code>switch</code> pesados por búsquedas en objetos/mapas.</li></ul></li></ul><h4 id="💻-practica-mitad-teoria-mitad-codigo" tabindex="-1">💻 Práctica: Mitad Teoría, Mitad Código <a class="header-anchor" href="#💻-practica-mitad-teoria-mitad-codigo" aria-label="Permalink to &quot;💻 Práctica: Mitad Teoría, Mitad Código&quot;">​</a></h4><ul><li><strong>Teoría:</strong> Resolución de matrices de verdad y análisis de flujo en papel.</li><li><strong>Práctica (Node.js):</strong> Creación de scripts que validen reglas de negocio complejas (ej. sistemas de permisos, calculadoras de impuestos con rangos, validación de formularios).</li></ul><hr><h3 id="📝-evaluacion-4-arquitectura-de-control-iterativo" tabindex="-1">📝 Evaluación 4: Arquitectura de Control Iterativo <a class="header-anchor" href="#📝-evaluacion-4-arquitectura-de-control-iterativo" aria-label="Permalink to &quot;📝 Evaluación 4: Arquitectura de Control Iterativo&quot;">​</a></h3><h2 id="evaluacion-en-el-laboratorio" tabindex="-1">Evaluacion en el laboratorio <a class="header-anchor" href="#evaluacion-en-el-laboratorio" aria-label="Permalink to &quot;Evaluacion en el laboratorio&quot;">​</a></h2><p><strong>Objetivo:</strong> Dominar la automatización de tareas redundantes mediante el uso eficiente de bucles y el control del flujo iterativo en JavaScript.</p><h4 id="_1-fundamentos-de-la-repeticion" tabindex="-1">1. Fundamentos de la Repetición <a class="header-anchor" href="#_1-fundamentos-de-la-repeticion" aria-label="Permalink to &quot;1. Fundamentos de la Repetición&quot;">​</a></h4><ul><li><strong>Concepto de Bucle:</strong> Abstracción de los saltos de bajo nivel hacia estructuras seguras y legibles.</li><li><strong>Ciclo de Vida de una Iteración:</strong><ul><li><strong>Inicialización:</strong> Definición del punto de partida.</li><li><strong>Condición de Permanencia:</strong> Evaluación booleana para continuar o salir.</li><li><strong>Actualización:</strong> Mutación de la variable de control (evitar el bucle infinito).</li></ul></li></ul><h4 id="_2-taxonomia-de-los-bucles" tabindex="-1">2. Taxonomía de los Bucles <a class="header-anchor" href="#_2-taxonomia-de-los-bucles" aria-label="Permalink to &quot;2. Taxonomía de los Bucles&quot;">​</a></h4><ul><li><strong>Bucles Determinados:</strong> Número de repeticiones conocido a priori.</li><li><strong>Bucles Indeterminados:</strong> Dependen de factores dinámicos (entradas de usuario, azar, datos externos).</li></ul><h4 id="_3-estructuras-fundamentales-en-js" tabindex="-1">3. Estructuras Fundamentales en JS <a class="header-anchor" href="#_3-estructuras-fundamentales-en-js" aria-label="Permalink to &quot;3. Estructuras Fundamentales en JS&quot;">​</a></h4><ul><li><strong>Bucle <code>for</code>:</strong> Integración de inicialización, condición y actualización en una sola cabecera. Ideal para rangos numéricos.</li><li><strong>Bucle <code>while</code>:</strong> Estructura de <strong>pre-condición</strong>. La ejecución depende de un estado que puede cambiar dinámicamente.</li><li><strong>Bucle <code>do...while</code>:</strong> Estructura de <strong>post-condición</strong>. Garantiza que el bloque de código se ejecute <strong>al menos una vez</strong>.</li></ul><h4 id="_4-control-fino-de-ejecucion" tabindex="-1">4. Control Fino de Ejecución <a class="header-anchor" href="#_4-control-fino-de-ejecucion" aria-label="Permalink to &quot;4. Control Fino de Ejecución&quot;">​</a></h4><ul><li><strong>Sentencia <code>break</code>:</strong> Finalización prematura de la estructura.</li><li><strong>Sentencia <code>continue</code>:</strong> Salto de la iteración actual para pasar a la siguiente.</li></ul><h4 id="_5-rendimiento-y-patologias" tabindex="-1">5. Rendimiento y Patologías <a class="header-anchor" href="#_5-rendimiento-y-patologias" aria-label="Permalink to &quot;5. Rendimiento y Patologías&quot;">​</a></h4><ul><li><strong>El Bucle Infinito:</strong> Causas y consecuencias (bloqueo del hilo único de Node.js / Event Loop).</li><li><strong>Prácticas Defensivas:</strong> Asegurar la progresión de la variable y evitar comparaciones estrictas con decimales.</li></ul><h4 id="💻-practica-de-cierre-de-trimestre" tabindex="-1">💻 Práctica de Cierre de Trimestre <a class="header-anchor" href="#💻-practica-de-cierre-de-trimestre" aria-label="Permalink to &quot;💻 Práctica de Cierre de Trimestre&quot;">​</a></h4><ul><li><strong>Ejercicios de Acumulación:</strong> Sumas, promedios y contadores.</li><li><strong>Validación de Entradas:</strong> Uso de <code>do...while</code> con <code>prompt-sync</code> para asegurar datos correctos.</li><li><strong>Lógica de Azar:</strong> Uso de <code>while</code> para procesos basados en condiciones aleatorias (simulaciones simples).</li></ul><hr><h2 id="✅-resumen-del-trimestre-1" tabindex="-1">✅ Resumen del Trimestre 1 <a class="header-anchor" href="#✅-resumen-del-trimestre-1" aria-label="Permalink to &quot;✅ Resumen del Trimestre 1&quot;">​</a></h2><p>Con estas 4 evaluaciones, el alumno ha pasado de la <strong>lógica pura en papel</strong> (Eval 1), a la <strong>configuración del entorno profesional</strong> (Eval 2), dominar la <strong>toma de decisiones dinámica</strong> (Eval 3) y finalmente automatizar procesos mediante <strong>iteración eficiente</strong> (Eval 4).</p>`,71)])])}const p=e(r,[["render",s]]);export{m as __pageData,p as default};
